    hashes={name:sha(path) for name,path in paths.items()};integrity={"schema_version":"tg4y.integrity.v1","files":{name:{"path":str(path.relative_to(root)),"sha256":hashes[name]} for name,path in paths.items()},"expected_frozen_hashes":{"tg4w_target_manifest":TARGET_SHA,"tg4w_evaluation_spec":SPEC_SHA},"frozen_hashes_match":hashes["tg4w_target_manifest"]==TARGET_SHA and hashes["tg4w_evaluation_spec"]==SPEC_SHA};dump(output/"artifact_integrity.json",integrity)
