    expected={(row["target_id"],row["provider"],row["seed"]) for row in local};observed={(row["target_id"],row["provider"],row["seed"]) for row in remote};exhaustive_only=sum(value=="exhaustive_only" for value in aws_summary["paired_outcomes"] for _ in range(aws_summary["paired_outcomes"][value]))
